CREATE TABLE IF NOT EXISTS public.wallet_accounts (id uuid DEFAULT gen_random_uuid() PRIMARY KEY, organization_id uuid NOT NULL UNIQUE REFERENCES public.organizations(id) ON DELETE CASCADE, currency text NOT NULL DEFAULT 'KES', balance numeric(14,2) NOT NULL DEFAULT 0 CHECK (balance >= 0), status text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','SUSPENDED','CLOSED')), updated_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now());